insert into t2 (`c_int`, `c_str`) values (1, 'clever haibt'), (4, 'kind margulis');
begin;
select * from t1 left join t2 on t1.c_int = t2.c_int for update;
-- curl http://$tidb_host:10080/mvcc/hex/7480000000000000005F728000000000000000
```

